/// The highest `mc_cache` schema migration this binary ships.
///
/// The store has no separate fence constant: `McStore::open` applies every bundled
/// migration on open, so the newest bundled migration IS the binary's supported
/// ceiling. Status surfaces report this value to answer "which schema does this
/// binary support" without a second source of truth that could drift from the
/// migration list.
pub const LATEST_MIGRATION_VERSION: u32 = {
    let mut latest = 0;
    let mut index = 0;
    while index < MIGRATIONS.len() {
        if MIGRATIONS[index].version > latest {
            latest = MIGRATIONS[index].version;
        }
        index += 1;
    }
    latest
};

/// Apply the route-to-identity vocabulary law inside the caller's fenced transaction.
/// Deletes only content twins, then rekeys remaining route rows and their mutation/note
/// companions. The authority predicate is repeated on every statement so a binding is
/// harmless until its domain is actually MODULE-owned.
fn normalize_authority_route_tx(
    tx: &rusqlite::Transaction<'_>,
    context_store_uuid: &str,
    project: &str,
    route_project_root: &str,
) -> rusqlite::Result<()> {
    tx.execute(
        "DELETE FROM mc_memories
          WHERE project_path = ?3
            AND EXISTS (
                SELECT 1 FROM mc_authority
                 WHERE context_store_uuid = ?1
                   AND project = ?2
                   AND domain = 'memories'
                   AND state = 'MODULE'
            )
            AND EXISTS (
                SELECT 1 FROM mc_memories canonical
                 WHERE canonical.project_path = ?2
                   AND canonical.category = mc_memories.category
                   AND canonical.normalized_hash = mc_memories.normalized_hash
            )",
        params![context_store_uuid, project, route_project_root],
    )?;
    tx.execute(
        "UPDATE mc_memories
            SET project_path = ?2
          WHERE project_path = ?3
            AND EXISTS (
                SELECT 1 FROM mc_authority
                 WHERE context_store_uuid = ?1
                   AND project = ?2
                   AND domain = 'memories'
                   AND state = 'MODULE'
            )",
        params![context_store_uuid, project, route_project_root],
    )?;
    tx.execute(
        "UPDATE mc_memory_mutation_log
            SET project_path = ?2
          WHERE project_path = ?3
            AND EXISTS (
                SELECT 1 FROM mc_authority
                 WHERE context_store_uuid = ?1
                   AND project = ?2
                   AND domain = 'memories'
                   AND state = 'MODULE'
            )",
        params![context_store_uuid, project, route_project_root],
    )?;
    tx.execute(
        "UPDATE mc_notes
            SET project_path = ?2
          WHERE project_path = ?3
            AND EXISTS (
                SELECT 1 FROM mc_authority
                 WHERE context_store_uuid = ?1
                   AND project = ?2
                   AND domain = 'notes'
                   AND state = 'MODULE'
            )",
        params![context_store_uuid, project, route_project_root],
    )?;
    Ok(())
}

/// A project's workspace membership: the union of member identities it reads, which of
/// them are its OWN (full visibility) vs FOREIGN (visible only in `share_categories`),
/// the shared-category allow-list, and per-foreign-member display attribution.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct WorkspaceMembership {
    /// All member project_paths (own + foreign), the union read set.
    pub union_identities: Vec<String>,
    /// The calling project's own identity (full-visibility).
    pub own_identity: String,
    /// Categories in which FOREIGN members' memories are shared into this project.
    pub share_categories: Vec<String>,
    /// project_path → display_name, for repo-attributing a foreign memory on render.
    pub display_name_by_path: std::collections::HashMap<String, String>,
}

fn workspace_membership_from_connection(
    conn: &rusqlite::Connection,
    project_path: &str,
) -> rusqlite::Result<Option<WorkspaceMembership>> {
    let workspace: Option<(i64, String)> = conn
        .query_row(
            "SELECT w.id, w.share_categories
               FROM mc_workspace_members m
               JOIN mc_workspaces w ON w.id = m.workspace_id
              WHERE m.project_path = ?1",
            params![project_path],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    let Some((workspace_id, share_categories_json)) = workspace else {
        return Ok(None);
    };

    let mut statement = conn.prepare(
        "SELECT project_path, display_name FROM mc_workspace_members
          WHERE workspace_id = ?1 ORDER BY project_path ASC",
    )?;
    let members: Vec<(String, String)> = statement
        .query_map(params![workspace_id], |row| Ok((row.get(0)?, row.get(1)?)))?
        .collect::<Result<Vec<_>, _>>()?;
    let union_identities = members.iter().map(|(path, _)| path.clone()).collect();
    let display_name_by_path = members.into_iter().collect();
    let share_categories = serde_json::from_str(&share_categories_json).unwrap_or_default();

    Ok(Some(WorkspaceMembership {
        union_identities,
        own_identity: project_path.to_string(),
        share_categories,
        display_name_by_path,
    }))
}

fn workspace_fingerprint_from_membership(membership: Option<&WorkspaceMembership>) -> String {
    let Some(membership) = membership else {
        return String::new();
    };
    // Membership rows are sorted by project_path; sorting categories makes policy order
    // independent as well.
    let mut shared = membership.share_categories.clone();
    shared.sort_unstable();
    let mut out = String::from("ws[");
    for identity in &membership.union_identities {
        out.push_str(&format!("m:{}:{};", identity.len(), identity));
    }
    out.push_str("|share:");
    for category in &shared {
        out.push_str(&format!("{}:{};", category.len(), category));
    }
    // Expiry is frozen at the last materialization timestamp and is intentionally excluded from
    // the workspace identity. Because time passing alone does not change that identity, expiry is
    // applied during the next normal hard materialization pass.
    out.push(']');
    out
}

/// A memory mutation-log entry. `update` is non-terminal (the memory is still present
/// with new content → renders `<updated>`); `archive`/`delete`/`superseded` are TERMINAL
/// (the memory left the active set → renders `<removed>`/`<superseded>`).
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct StoredMemoryMutation {
    pub id: i64,
    pub mutation_type: String,
    pub target_memory_id: i64,
    pub superseded_by_id: Option<i64>,
    pub category: Option<String>,
    pub new_content: Option<String>,
    /// True when at least one coalesced row records a foreign-visibility transition.
    /// The marker is derived from the internal mutation category and is not persisted separately.
    pub visibility_changed: bool,
    pub queued_at: i64,
}

impl StoredMemoryMutation {
    fn is_terminal(&self) -> bool {
        matches!(
            self.mutation_type.as_str(),
            "archive" | "delete" | "superseded"
        )
    }
}

/// The durable historian single-flight phase. The phase lives in [`ModuleMeta`] so
/// the same row-version CAS that guards cache-state commits also guards writer
/// orchestration: a stale producer can never publish against a newer module state.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum HistorianPhase {
    #[default]
    Idle,
    Firing,
    AwaitingProducer,
    Validating,
    Publishing,
}

impl HistorianPhase {
    pub fn as_str(&self) -> &'static str {
        match self {
            HistorianPhase::Idle => "idle",
            HistorianPhase::Firing => "firing",
            HistorianPhase::AwaitingProducer => "awaiting_producer",
            HistorianPhase::Validating => "validating",
            HistorianPhase::Publishing => "publishing",
        }
    }
}

/// Inclusive ordinal range pinned for one historian run.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct HistorianChunkRange {
    pub from_ordinal: u64,
    pub to_ordinal: u64,
}

/// Content-sensitive identity for one message selected into a historian firing.
/// The outer firing vector preserves message order; each block vector preserves
/// the canonical block order already tracked by [`ModuleMeta::block_identity_by_mid`].
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct HistorianSelectedMessageIdentity {
    pub mid: String,
    pub block_identities: Vec<BlockIdentity>,
}

/// The durable historian state stored inside [`ModuleMeta`]. Idle keeps
/// `firing_seq` as the monotonic last-issued sequence and clears the in-flight
/// identifiers; abandon paths additionally set `failure_backoff_at_ms`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct HistorianDurableState {
    #[serde(default)]
    pub state: HistorianPhase,
    #[serde(default)]
    pub firing_seq: u64,
    #[serde(default)]
    pub chunk_range: Option<HistorianChunkRange>,
    #[serde(default)]
    pub chunk_fingerprint: String,
    /// Durable content identities for exactly the message range sent to the producer.
    /// Publication compares these with the current store metadata inside the write
    /// transaction, allowing later tail extension while rejecting selected-byte drift.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub selected_range_identities: Vec<HistorianSelectedMessageIdentity>,
    #[serde(default)]
    pub producer_session_id: Option<String>,
    #[serde(default)]
    pub producer_run_id: Option<String>,
    #[serde(default)]
    pub fired_at_ms: Option<i64>,
    /// Session-level revert epoch observed when the chunk was assembled. It is copied
    /// into the firing state so a producer reattached after restart publishes against the
    /// same epoch it originally saw, not the session's current epoch.
    #[serde(default)]
    pub expected_revert_epoch: u64,
    /// The compartment-set generation observed with the firing snapshot. Publication
    /// rechecks it inside its transaction so an overlapping external sync cannot slip
    /// between the producer's snapshot and the append.
    #[serde(default)]
    pub compartment_set_generation: CompartmentSetGeneration,
    #[serde(default)]
    pub failure_backoff_at_ms: Option<i64>,
    /// Human-readable detail of the most recent failed firing. The producer runs in a
    /// spawned task whose stderr a supervised deployment never captures, so the error
    /// must live in durable state to be diagnosable from a state dump. Cleared when a
    /// later firing establishes its producer run.
    #[serde(default)]
    pub last_failure: Option<String>,
    /// Why the most recent pass declined to fire. The structured text retains the raw Rust
    /// cause, a TypeScript-aligned canonical cause, and quantized measurements when available.
    /// Its change gate prevents steady-state passes from rewriting the row. The twin of
    /// `last_failure` for the pre-fire half: a supervised rig cannot read the transform response's
    /// diagnostics block, so the skip branch must be readable from the state dump. Cleared on fire.
    #[serde(default)]
    pub last_no_fire: Option<String>,
    /// Consecutive failures on the historian publication path. This is diagnostic-only
    /// state: it makes repeated fence/outbox failures visible without affecting bytes.
    #[serde(default)]
    pub consecutive_publish_failures: u32,
}

impl Default for HistorianDurableState {
    fn default() -> Self {
        HistorianDurableState {
            state: HistorianPhase::Idle,
            firing_seq: 0,
            chunk_range: None,
            chunk_fingerprint: String::new(),
            selected_range_identities: Vec::new(),
            producer_session_id: None,
            producer_run_id: None,
            fired_at_ms: None,
            expected_revert_epoch: 0,
            compartment_set_generation: CompartmentSetGeneration::default(),
            failure_backoff_at_ms: None,
            last_failure: None,
            last_no_fire: None,
            consecutive_publish_failures: 0,
        }
    }
}

/// One accepted pass in the bounded scheduler history attached to [`PassTrace`].
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct PassSchedulerObservation {
    pub timestamp_ms: i64,
    /// Detailed Rust pass band retained for existing incident tooling.
    pub scheduler_decision: String,
    /// Execute/defer class shared with TypeScript `transform_decisions`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub canonical_decision: Option<String>,
    /// Canonical TypeScript refusal reason when the final class is defer.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub defer_reason: Option<String>,
    pub drain_latch_active: bool,
}

/// Incident-worthy scheduler evidence retained independently of the recency ring.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct InterestingPassSchedulerObservation {
    pub timestamp_ms: i64,
    pub scheduler_decision: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub canonical_decision: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub defer_reason: Option<String>,
    pub drain_latch_active: bool,
    /// Sender-stamped request instant. Missing remains missing; it is never backfilled from the
    /// module clock because the two clocks are not interchangeable correlation keys.
    pub request_observed_at_ms: Option<u64>,
    /// Caller-owned full-array fingerprint echoed by the transform response. This is omitted
    /// only when the caller supplied no identity or exceeded the diagnostic byte bound.
    pub full_array_fingerprint: Option<String>,
    /// Live superseded tool arcs observed when the ride gate opened, before downstream filters.
    /// Missing means the gate stayed shut and selection did not run; zero is an observed empty set.
    #[serde(default)]
    pub eligible_supersession_count: Option<u64>,
    /// Eligible supersession arcs whose final decisions were entirely removed by the newest-tag
    /// block window. Unit: tool arcs.
    #[serde(default)]
    pub withheld_by_tag_window: Option<u64>,
    /// Eligible supersession arcs whose final decisions were entirely removed by mutation-exempt
    /// or lineage-anchor messages. Unit: tool arcs.
    #[serde(default)]
    pub withheld_by_exempt_message: Option<u64>,
    /// Eligible supersession tool arcs represented in the final reduction decision list.
    #[serde(default)]
    pub applied_supersession_count: Option<u64>,
}

impl InterestingPassSchedulerObservation {
    fn from_observation(
        observation: &PassSchedulerObservation,
        request_observed_at_ms: Option<u64>,
        full_array_fingerprint: Option<&str>,
        eligible_supersession_count: Option<u64>,
        withheld_by_tag_window: Option<u64>,
        withheld_by_exempt_message: Option<u64>,
        applied_supersession_count: Option<u64>,
    ) -> Self {
        Self {
            timestamp_ms: observation.timestamp_ms,
            scheduler_decision: observation.scheduler_decision.clone(),
            canonical_decision: observation.canonical_decision.clone(),
            defer_reason: observation.defer_reason.clone(),
            drain_latch_active: observation.drain_latch_active,
            request_observed_at_ms,
            full_array_fingerprint: full_array_fingerprint
                .filter(|fingerprint| fingerprint.len() <= MAX_FULL_ARRAY_FINGERPRINT_BYTES)
                .map(str::to_string),
            eligible_supersession_count,
            withheld_by_tag_window,
            withheld_by_exempt_message,
            applied_supersession_count,
        }
    }
}

fn serialize_scheduler_observation(
    observation: &PassSchedulerObservation,
) -> Result<String, McStoreError> {
    if !matches!(
        observation.scheduler_decision.as_str(),
        "Defer" | "Execute" | "Force85" | "Emergency95"
    ) {
        return Err(McStoreError::Serde(format!(
            "unknown scheduler decision {:?}",
            observation.scheduler_decision
        )));
    }
    if let Some(canonical_decision) = observation.canonical_decision.as_deref() {
        let expected = if observation.scheduler_decision == "Defer" {
            "defer"
        } else {
            "execute"
        };
        if canonical_decision != expected {
            return Err(McStoreError::Serde(format!(
                "scheduler pass {} requires canonical decision {expected}, got {canonical_decision}",
                observation.scheduler_decision
            )));
        }
    }
    if let Some(defer_reason) = observation.defer_reason.as_deref() {
        if observation.scheduler_decision != "Defer"
            || !matches!(defer_reason, "scheduler_defer" | "mid_turn_boundary")
        {
            return Err(McStoreError::Serde(format!(
                "invalid scheduler defer reason {defer_reason} for pass {}",
                observation.scheduler_decision
            )));
        }
    }
    serde_json::to_string(observation).map_err(|error| McStoreError::Serde(error.to_string()))
}

fn scheduler_pass_is_interesting(
    applied_reduction: bool,
    produced_output_divergence: bool,
) -> bool {
    applied_reduction || produced_output_divergence
}

fn serialize_interesting_scheduler_observation(
    observation: &PassSchedulerObservation,
    request_observed_at_ms: Option<u64>,
    full_array_fingerprint: Option<&str>,
    eligible_supersession_count: Option<u64>,
    withheld_by_tag_window: Option<u64>,
    withheld_by_exempt_message: Option<u64>,
    applied_supersession_count: Option<u64>,
) -> Result<String, McStoreError> {
    serde_json::to_string(&InterestingPassSchedulerObservation::from_observation(
        observation,
        request_observed_at_ms,
        full_array_fingerprint,
        eligible_supersession_count,
        withheld_by_tag_window,
        withheld_by_exempt_message,
        applied_supersession_count,
    ))
    .map_err(|error| McStoreError::Serde(error.to_string()))
}

