    #[test]
    fn scheduler_interesting_history_queries_time_and_shared_request_identity() {
        let dir = tempfile::tempdir().unwrap();
        let store = McStore::open(&descriptor(dir.path())).unwrap();
        let entries = [
            (100, "Execute", 9_001, "fingerprint-a"),
            (100, "Force85", 9_024, "fingerprint-b"),
            (300, "Emergency95", 9_300, "fingerprint-c"),
        ];
        let mut expected = None;
        for (timestamp_ms, decision, request_time, fingerprint) in entries {
            expected = Some(commit_scheduler_observation(
                &store,
                "interesting-query",
                expected,
                &PassSchedulerObservation {
                    timestamp_ms,
                    scheduler_decision: decision.to_string(),
                    canonical_decision: None,
                    defer_reason: None,
                    drain_latch_active: decision == "Execute",
                },
                (false, Some(3), Some(0), Some(0), Some(3), 1),
                Some(request_time),
                Some(fingerprint),
            ));
        }

        let range = store
            .load_interesting_pass_scheduler_history("interesting-query", 100, 299)
            .unwrap();
        assert_eq!(range.len(), 2, "the module-clock range is inclusive");
        assert_eq!(range[0].scheduler_decision, "Execute");
        assert_eq!(range[1].scheduler_decision, "Force85");

        for (request_time, fingerprint, expected_decision) in [
            (9_001, "fingerprint-a", "Execute"),
            (9_024, "fingerprint-b", "Force85"),
        ] {
            let by_request_time = store
                .load_interesting_pass_scheduler_history_by_request_time(
                    "interesting-query",
                    request_time,
                )
                .unwrap();
            assert_eq!(by_request_time.len(), 1);
            assert_eq!(by_request_time[0].scheduler_decision, expected_decision);
            assert_eq!(
                by_request_time[0].full_array_fingerprint.as_deref(),
                Some(fingerprint)
            );

            let by_fingerprint = store
                .load_interesting_pass_scheduler_history_by_fingerprint(
                    "interesting-query",
                    fingerprint,
                )
                .unwrap();
            assert_eq!(by_fingerprint.len(), 1);
            assert_eq!(by_fingerprint[0].scheduler_decision, expected_decision);
            assert_eq!(by_fingerprint[0].request_observed_at_ms, Some(request_time));
        }

        commit_scheduler_observation(
            &store,
            "interesting-query",
            expected,
            &PassSchedulerObservation {
                timestamp_ms: 400,
                scheduler_decision: "Force85".to_string(),
                canonical_decision: None,
                defer_reason: None,
                drain_latch_active: false,
            },
            (false, Some(3), Some(0), Some(0), Some(3), 1),
            None,
            Some("fingerprint-without-sender-time"),
        );
        let absent = store
            .load_interesting_pass_scheduler_history_by_fingerprint(
                "interesting-query",
                "fingerprint-without-sender-time",
            )
            .unwrap();
        assert_eq!(absent.len(), 1);
        assert_eq!(absent[0].request_observed_at_ms, None);
    }

    #[test]
    fn scheduler_interest_includes_reductions_and_output_divergence_on_defer() {
        let dir = tempfile::tempdir().unwrap();
        let store = McStore::open(&descriptor(dir.path())).unwrap();
        let core = CoreState::default();
        let meta = ModuleMeta::default();
        let observation = PassSchedulerObservation {
            timestamp_ms: 500,
            scheduler_decision: "Defer".to_string(),
            canonical_decision: None,
            defer_reason: None,
            drain_latch_active: false,
        };

        for (session_id, first_divergence, applied_reductions, fingerprint) in [
            ("divergence-interest", Some("{}"), false, "diverged"),
            ("reduction-interest", None, true, "reduced"),
        ] {
            store
                .commit_transform(
                    session_id,
                    TransformCommit {
                        expected: None,
                        core: &core,
                        meta: &meta,
                        consumed_drop_ids: &[],
                        first_applied_command_ids: &[],
                        memory_revision: None,
                        compartment_max_seq: None,
                        project_root: None,
                        first_divergence,
                        scheduler_observation: Some(&observation),
                        scheduler_request_observed_at_ms: Some(500),
                        scheduler_full_array_fingerprint: Some(fingerprint),
                        scheduler_eligible_supersession_count: None,
                        scheduler_withheld_by_tag_window: None,
                        scheduler_withheld_by_exempt_message: None,
                        scheduler_applied_supersession_count: None,
                        scheduler_applied_reductions: applied_reductions,
                        overlays: TransformOverlayBatch::default(),
                    },
                )
                .unwrap();
            let retained = store
                .load_interesting_pass_scheduler_history(session_id, 500, 500)
                .unwrap();
            assert_eq!(retained.len(), 1);
            assert_eq!(retained[0].scheduler_decision, "Defer");
            assert_eq!(
                retained[0].eligible_supersession_count, None,
                "Defer did not run supersession selection, so its depth must remain absent"
            );
            assert_eq!(
                retained[0].full_array_fingerprint.as_deref(),
                Some(fingerprint)
            );
        }
    }

    #[test]
    fn migration_44_merges_generation_twins_and_keeps_unmatched_identityless_rows() {
        let conn = rusqlite::Connection::open_in_memory().unwrap();
        conn.execute_batch(
            "CREATE TABLE mc_authority_route_bindings (
                 route_project_root TEXT PRIMARY KEY,
                 context_store_uuid TEXT NOT NULL,
                 project TEXT NOT NULL
             );
             CREATE TABLE mc_memories (
                 id INTEGER PRIMARY KEY,
                 project_path TEXT NOT NULL,
                 category TEXT NOT NULL,
                 content TEXT NOT NULL,
                 normalized_hash TEXT NOT NULL,
                 updated_at INTEGER NOT NULL,
                 verified_at INTEGER,
                 classified_at INTEGER,
                 context_store_uuid TEXT,
                 context_row_id INTEGER
             );
             INSERT INTO mc_authority_route_bindings
                 (route_project_root, context_store_uuid, project)
             VALUES ('/repo', 'current-store', 'git:project');
             INSERT INTO mc_memories
                 (id, project_path, category, content, normalized_hash, updated_at,
                  verified_at, classified_at, context_store_uuid, context_row_id)
             VALUES
                 (1, 'git:project', 'CONSTRAINTS', 'current', 'same-hash', 10,
                  20, NULL, 'current-store', 101),
                 (2, 'git:project', 'CONSTRAINTS', 'stale', 'same-hash', 30,
                  NULL, 40, 'stale-store', 202),
                 (3, 'git:project', 'CONSTRAINTS', 'identityless twin', 'same-hash', 25,
                  35, 30, '', NULL),
                 (4, 'git:project', 'ARCHITECTURE', 'module original', 'unmatched-hash', 50,
                  60, 70, '', NULL);",
        )
        .unwrap();

        let migration = MIGRATIONS
            .iter()
            .find(|migration| migration.version == 44)
            .unwrap();
        conn.execute_batch(migration.statements).unwrap();

        let current = conn
            .query_row(
                "SELECT content, updated_at, verified_at, classified_at,
                        context_store_uuid, context_row_id
                   FROM mc_memories WHERE id = 1",
                [],
                |row| {
                    Ok((
                        row.get::<_, String>(0)?,
                        row.get::<_, i64>(1)?,
                        row.get::<_, Option<i64>>(2)?,
                        row.get::<_, Option<i64>>(3)?,
                        row.get::<_, Option<String>>(4)?,
                        row.get::<_, Option<i64>>(5)?,
                    ))
                },
            )
            .unwrap();
        assert_eq!(
            current,
            (
                "current".to_string(),
                30,
                Some(35),
                Some(40),
                Some("current-store".to_string()),
                Some(101),
            )
        );
        let remaining = conn
            .prepare("SELECT id, context_store_uuid FROM mc_memories ORDER BY id")
            .unwrap()
            .query_map([], |row| {
                Ok((row.get::<_, i64>(0)?, row.get::<_, Option<String>>(1)?))
            })
            .unwrap()
            .collect::<Result<Vec<_>, _>>()
            .unwrap();
        assert_eq!(
            remaining,
            vec![
                (1, Some("current-store".to_string())),
                (4, Some(String::new())),
            ],
            "only natural-key twins are merged; an unmatched module-authored row survives"
        );
    }

    #[test]
    fn migration_45_merges_three_stale_generations_without_a_current_row() {
        let conn = rusqlite::Connection::open_in_memory().unwrap();
        conn.execute_batch(
            "CREATE TABLE mc_authority_route_bindings (
                 route_project_root TEXT PRIMARY KEY,
                 context_store_uuid TEXT NOT NULL,
                 project TEXT NOT NULL
             );
             CREATE TABLE mc_memories (
                 id INTEGER PRIMARY KEY,
                 project_path TEXT NOT NULL,
                 category TEXT NOT NULL,
                 content TEXT NOT NULL,
                 normalized_hash TEXT NOT NULL,
                 updated_at INTEGER NOT NULL,
                 verified_at INTEGER,
                 classified_at INTEGER,
                 context_store_uuid TEXT,
                 context_row_id INTEGER
             );
             INSERT INTO mc_authority_route_bindings
                 (route_project_root, context_store_uuid, project)
             VALUES ('/repo', 'current-store', 'git:project');
             INSERT INTO mc_memories
                 (id, project_path, category, content, normalized_hash, updated_at,
                  verified_at, classified_at, context_store_uuid, context_row_id)
             VALUES
                 (1, 'git:project', 'CONSTRAINTS', 'old generation', 'same-hash', 10,
                  90, NULL, 'old-store-a', 101),
                 (2, 'git:project', 'CONSTRAINTS', 'new generation', 'same-hash', 30,
                  NULL, 70, 'old-store-b', 202),
                 (3, 'git:project', 'CONSTRAINTS', 'newest id wins tie', 'same-hash', 30,
                  80, 60, '', NULL);",
        )
        .unwrap();

        let migration = MIGRATIONS
            .iter()
            .find(|migration| migration.version == 45)
            .unwrap();
        conn.execute_batch(migration.statements).unwrap();

        let survivor = conn
            .query_row(
                "SELECT id, content, updated_at, verified_at, classified_at,
                        context_store_uuid, context_row_id
                   FROM mc_memories",
                [],
                |row| {
                    Ok((
                        row.get::<_, i64>(0)?,
                        row.get::<_, String>(1)?,
                        row.get::<_, i64>(2)?,
                        row.get::<_, Option<i64>>(3)?,
                        row.get::<_, Option<i64>>(4)?,
                        row.get::<_, Option<String>>(5)?,
                        row.get::<_, Option<i64>>(6)?,
                    ))
                },
            )
            .unwrap();
        assert_eq!(
            survivor,
            (
                3,
                "newest id wins tie".to_string(),
                30,
                Some(90),
                Some(70),
                Some(String::new()),
                None,
            )
        );
        assert_eq!(
            conn.query_row("SELECT COUNT(*) FROM mc_memories", [], |row| row
                .get::<_, i64>(0))
                .unwrap(),
            1
        );
    }

    fn rebuild_mc_memories_without_natural_unique(path: &std::path::Path) {
        let conn = rusqlite::Connection::open(path).unwrap();
        let table_sql: String = conn
            .query_row(
                "SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'mc_memories'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        let replacement = table_sql.replace(
            ",\n            UNIQUE(project_path, category, normalized_hash)",
            "",
        );
        assert_ne!(
            replacement, table_sql,
            "fixture must remove the natural-key UNIQUE"
        );
        let schema_objects = conn
            .prepare(
                "SELECT sql FROM sqlite_master
                  WHERE tbl_name = 'mc_memories'
                    AND type IN ('index', 'trigger')
                    AND sql IS NOT NULL
                  ORDER BY type, name",
            )
            .unwrap()
            .query_map([], |row| row.get::<_, String>(0))
            .unwrap()
            .collect::<Result<Vec<_>, _>>()
            .unwrap();

        conn.execute_batch("PRAGMA foreign_keys = OFF; BEGIN IMMEDIATE;")
            .unwrap();
        conn.execute_batch("ALTER TABLE mc_memories RENAME TO mc_memories_with_natural_unique;")
            .unwrap();
        conn.execute_batch(&replacement).unwrap();
        conn.execute_batch(
            "INSERT INTO mc_memories SELECT * FROM mc_memories_with_natural_unique;
             DROP TABLE mc_memories_with_natural_unique;",
        )
        .unwrap();
        for schema_sql in schema_objects {
            conn.execute_batch(&schema_sql).unwrap();
        }
        conn.execute_batch("COMMIT; PRAGMA foreign_keys = ON;")
            .unwrap();
    }

    #[test]
    fn authority_seed_adopts_one_all_stale_twin_and_coalesces_the_rest() {
        let dir = tempfile::tempdir().unwrap();
        let initial = McStore::open(&descriptor(dir.path())).unwrap();
        drop(initial);
        rebuild_mc_memories_without_natural_unique(&dir.path().join("store.db"));
        let store = McStore::open(&descriptor(dir.path())).unwrap();
        store
            .inner
            .with_conn_fenced(|tx| {
                tx.execute_batch(
                    "INSERT INTO mc_memories
                         (id, project_path, category, content, normalized_hash, importance,
                          status, first_seen_at, created_at, updated_at, last_seen_at,
                          verification_status, verified_at, classified_at,
                          context_store_uuid, context_row_id)
                     VALUES
                         (700, 'git:project', 'CONSTRAINTS', 'older stale', 'same-hash', 10,
                          'active', 1, 2, 500, 3, 'verified', 900, NULL,
                          'stale-store-a', 9),
                         (701, 'git:project', 'CONSTRAINTS', 'newer stale', 'same-hash', 20,
                          'active', 1, 2, 700, 3, 'verified', NULL, 1000,
                          'stale-store-b', 10);",
                )?;
                Ok(())
            })
            .unwrap();
        let incoming = AuthoritySeedRow {
            source_row_id: 42,
            snapshot: serde_json::json!({
                "id": 42,
                "project_path": "git:project",
                "category": "CONSTRAINTS",
                "content": "restored content",
                "normalized_hash": "same-hash",
                "importance": 80,
                "first_seen_at": 10,
                "created_at": 20,
                "updated_at": 800,
                "last_seen_at": 30,
                "status": "active",
                "verification_status": "verified",
                "verified_at": 700,
                "classified_at": 600
            }),
        };

        let ids = store
            .seed_authority_rows(
                "current-store",
                "git:project",
                "memories",
                std::slice::from_ref(&incoming),
            )
            .unwrap();
        assert_eq!(
            ids,
            vec![701],
            "newest stale row is adopted deterministically"
        );
        let adopted = store.get_memory_full(701).unwrap().unwrap();
        assert_eq!(adopted.content, "restored content");
        assert_eq!(adopted.updated_at, 800);
        assert_eq!(adopted.verified_at, Some(900));
        assert_eq!(adopted.classified_at, Some(1000));
        assert_eq!(adopted.context_store_uuid.as_deref(), Some("current-store"));
        assert_eq!(adopted.context_row_id, Some(42));
        let remaining = store
            .inner
            .with_conn(|conn| {
                conn.query_row(
                    "SELECT COUNT(*) FROM mc_memories
                      WHERE project_path = 'git:project'
                        AND category = 'CONSTRAINTS'
                        AND normalized_hash = 'same-hash'",
                    [],
                    |row| row.get::<_, i64>(0),
                )
            })
            .unwrap();
        assert_eq!(remaining, 1);
    }

    #[test]
    fn authority_seed_same_batch_natural_duplicates_alias_to_the_last_snapshot() {
        let dir = tempfile::tempdir().unwrap();
        let store = McStore::open(&descriptor(dir.path())).unwrap();
        let rows = [
            AuthoritySeedRow {
                source_row_id: 100,
                snapshot: serde_json::json!({
                    "id": 100,
                    "project_path": "git:project",
                    "category": "CONSTRAINTS",
                    "content": "first snapshot",
                    "normalized_hash": "same-hash",
                    "updated_at": 100,
                    "status": "active"
                }),
            },
            AuthoritySeedRow {
                source_row_id: 200,
                snapshot: serde_json::json!({
                    "id": 200,
                    "project_path": "git:project",
                    "category": "CONSTRAINTS",
                    "content": "last snapshot",
                    "normalized_hash": "same-hash",
                    "updated_at": 200,
                    "status": "active"
                }),
            },
            AuthoritySeedRow {
                source_row_id: 300,
                snapshot: serde_json::json!({
                    "id": 300,
                    "project_path": "git:project",
                    "category": "ARCHITECTURE",
                    "content": "references the first alias",
                    "normalized_hash": "other-hash",
                    "updated_at": 300,
                    "status": "active",
                    "superseded_by_memory_id": 100
                }),
            },
        ];

        let ids = store
            .seed_authority_rows("current-store", "git:project", "memories", &rows)
            .unwrap();
        assert_eq!(
            ids[0], ids[1],
            "both source ids alias the surviving module row"
        );
        assert_ne!(ids[1], ids[2]);
        let survivor = store.get_memory_full(ids[1]).unwrap().unwrap();
        assert_eq!(survivor.content, "last snapshot");
        assert_eq!(survivor.context_row_id, Some(200));
        assert_eq!(
            store
                .get_memory_full(ids[2])
                .unwrap()
                .unwrap()
                .superseded_by_memory_id,
            Some(ids[1]),
            "pending references through either source alias resolve to the survivor"
        );
        let count = store
            .inner
            .with_conn(|conn| {
                conn.query_row(
                    "SELECT COUNT(*) FROM mc_memories
                      WHERE project_path = 'git:project'
                        AND category = 'CONSTRAINTS'
                        AND normalized_hash = 'same-hash'",
                    [],
                    |row| row.get::<_, i64>(0),
                )
            })
            .unwrap();
        assert_eq!(count, 1);
    }

    #[test]
    fn project_mural_artifact_upsert_is_hash_gated() {
        let dir = tempfile::tempdir().unwrap();
        let store = McStore::open(&descriptor(dir.path())).unwrap();

        assert!(store
            .upsert_project_mural_artifact(
                "git:project",
                b"data:image/png;base64,YQ==",
                "mural-a",
                100,
            )
            .unwrap());
        let first = store
            .load_project_mural_artifact("git:project")
            .unwrap()
            .unwrap();
        assert_eq!(first.data_url, b"data:image/png;base64,YQ==");
        assert_eq!(first.content_hash, "mural-a");
        assert_eq!(first.updated_at, 100);

        assert!(!store
            .upsert_project_mural_artifact(
                "git:project",
                b"data:image/png;base64,unexpected-but-same-hash",
                "mural-a",
                200,
            )
            .unwrap());
        let unchanged = store
            .load_project_mural_artifact("git:project")
            .unwrap()
            .unwrap();
        assert_eq!(
            unchanged, first,
            "same hash must not bump artifact identity"
        );

        assert!(store
            .upsert_project_mural_artifact(
                "git:project",
                b"data:image/png;base64,Yg==",
                "mural-b",
                300,
            )
            .unwrap());
        assert_eq!(
            store
                .load_project_mural_artifact("git:project")
                .unwrap()
                .unwrap(),
            ProjectMuralArtifact {
                project_path: "git:project".to_string(),
                data_url: b"data:image/png;base64,Yg==".to_vec(),
                content_hash: "mural-b".to_string(),
                updated_at: 300,
            }
        );
    }

